259→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
260→// When force is true, it amends without prompting.
261→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
262→	// Get HEAD commit info
263→	repo, err := openRepository(ctx)
264→	if err != nil {
265→		return fmt.Errorf("failed to open repository: %w", err)
266→	}
267→	headRef, err := repo.Head()
268→	if err != nil {
269→		return fmt.Errorf("failed to get HEAD: %w", err)
270→	}
271→	headCommit, err := repo.CommitObject(headRef.Hash())
272→	if err != nil {
273→		return fmt.Errorf("failed to get HEAD commit: %w", err)
274→	}
275→
276→	shortHash := headRef.Hash().String()[:7]
277→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
278→
279→	// Check if the commit already has this checkpoint trailer
280→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
281→		fmt.Fprintf(w, "\nLast commit already has an Entire-Checkpoint trailer.\n")
282→		return nil
283→	}
284→
285→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
286→
287→	amend := true
288→	if !force {
289→		form := NewAccessibleForm(
290→			huh.NewGroup(
291→				huh.NewConfirm().
292→					Title("Amend to last commit in this branch?").
293→					Affirmative("Y").
294→					Negative("n").
295→					Value(&amend),
296→			),
297→		)
298→		if err := form.Run(); err != nil {
299→			return fmt.Errorf("prompt failed: %w", err)
300→		}
301→	}
302→
303→	if !amend {
304→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
305→		return nil
306→	}
307→
308→	// Amend the commit with the checkpoint trailer
309→	newMessage := fmt.Sprintf("%s\n\n%s: %s\n", strings.TrimRight(headCommit.Message, "\n"), trailers.CheckpointTrailerKey, checkpointIDStr)
310→
311→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
312→	if output, err := cmd.CombinedOutput(); err != nil {
313→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
314→	}
315→
316→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
317→	return nil
318→}
