121→// FindCheckpointUUID finds the UUID of the message containing the tool_result
122→// for the given tool_use_id. This is used to find the checkpoint point for
123→// transcript truncation when rewinding to a task.
124→// Returns the UUID and true if found, empty string and false otherwise.
125→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
126→	for _, line := range transcript {
127→		if line.Type != transcriptTypeUser {
128→			continue
129→		}
130→
131→		var msg userMessageWithToolResults
132→		if err := json.Unmarshal(line.Message, &msg); err != nil {
133→			continue
134→		}
135→
136→		for _, block := range msg.Content {
137→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
138→				return line.UUID, true
139→			}
140→		}
141→	}
142→	return "", false
143→}
