165→// writeTranscript writes transcript lines to a file in JSONL format.
166→func writeTranscript(path string, transcript []transcriptLine) error {
167→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
168→	if err != nil {
169→		return fmt.Errorf("failed to create file: %w", err)
170→	}
171→	defer func() { _ = file.Close() }()
172→
173→	for _, line := range transcript {
174→		data, err := json.Marshal(line)
175→		if err != nil {
176→			return fmt.Errorf("failed to marshal line: %w", err)
177→		}
178→		if _, err := file.Write(data); err != nil {
179→			return fmt.Errorf("failed to write line: %w", err)
180→		}
181→		if _, err := file.WriteString("\n"); err != nil {
182→			return fmt.Errorf("failed to write newline: %w", err)
183→		}
184→	}
185→
186→	return nil
187→}
