// searchTranscriptInSubdirs searches for a session transcript across all Claude project
// directories that correspond to subdirectories of the repo root. Claude Code uses cwd
// (not repo root) for its project directory, so sessions started from subdirectories
// are stored under different project directory names.
func searchTranscriptInSubdirs(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", fmt.Errorf("failed to get worktree root: %w", err)
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectsDir := filepath.Join(homeDir, ".claude", "projects")
	entries, err := os.ReadDir(projectsDir)
	if err != nil {
		return "", fmt.Errorf("failed to read projects directory: %w", err)
	}

	// The repo root sanitized is the prefix for all matching project dirs.
	// e.g. repo at /Users/username/cli → prefix "-Users-username-cli"
	// Session started from /Users/username/cli/cmd → dir "-Users-username-cli-cmd"
	repoPrefix := sanitizePathForSearch(repoRoot)

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		name := entry.Name()
		// Must start with the repo prefix and either be exactly the prefix
		// (already checked by resolveTranscriptPath) or be a subdirectory of it.
		if name == repoPrefix || !hasPathPrefix(name, repoPrefix) {
			continue
		}
		candidate := agent.ResolveSessionFile(filepath.Join(projectsDir, name), sessionID)
		if _, statErr := os.Stat(candidate); statErr == nil {
			return candidate, nil
		}
	}

	return "", errors.New("transcript not found in any subdirectory project dir")
}

